/* ═══════════════════════════════════════════════════════
   RURAL ELITE — Meta Pixel Events
   ═══════════════════════════════════════════════════════ */

(function () {
  'use strict';

  // Scroll depth tracking
  let tracked25 = false, tracked50 = false, tracked75 = false;

  function getScrollPercent() {
    const h = document.documentElement;
    const b = document.body;
    const st = h.scrollTop || b.scrollTop;
    const sh = (h.scrollHeight || b.scrollHeight) - h.clientHeight;
    return sh > 0 ? (st / sh) * 100 : 0;
  }

  window.addEventListener('scroll', function () {
    if (typeof fbq !== 'function') return;
    const pct = getScrollPercent();

    if (!tracked25 && pct >= 25) {
      tracked25 = true;
      fbq('trackCustom', 'ScrollDepth', { depth: '25%' });
    }
    if (!tracked50 && pct >= 50) {
      tracked50 = true;
      fbq('trackCustom', 'ScrollDepth', { depth: '50%' });
    }
    if (!tracked75 && pct >= 75) {
      tracked75 = true;
      fbq('trackCustom', 'ScrollDepth', { depth: '75%' });
    }
  }, { passive: true });

  // Time on page tracking
  setTimeout(function () {
    if (typeof fbq === 'function') {
      fbq('trackCustom', 'TimeOnPage', { seconds: 30 });
    }
  }, 30000);

  setTimeout(function () {
    if (typeof fbq === 'function') {
      fbq('trackCustom', 'TimeOnPage', { seconds: 60 });
    }
  }, 60000);

})();
